import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken());
        String x = st.nextToken(), y = st.nextToken(), z = st.nextToken();
        // Rightmost position whose z letter differs from both x and y: drop it from that class only.
        int star = -1;
        for (int i = n - 1; i >= 0; i--)
            if (z.charAt(i) != x.charAt(i) && z.charAt(i) != y.charAt(i)) { star = i; break; }
        if (star < 0) { System.out.println("-1"); return; }
        byte[] full = "[ABCDEFGHIJKLMNOPQRSTUVWXYZ]".getBytes();
        byte[] reduced = ("[" + "ABCDEFGHIJKLMNOPQRSTUVWXYZ".replace(String.valueOf(z.charAt(star)), "") + "]").getBytes();
        byte[] out = new byte[28 * n];  // 28n - 1 characters plus the newline
        int p = 0;
        for (int i = 0; i < n; i++) {
            byte[] g = i == star ? reduced : full;
            System.arraycopy(g, 0, out, p, g.length);
            p += g.length;
        }
        out[p++] = '\n';
        OutputStream os = new BufferedOutputStream(System.out, 1 << 16);
        os.write(out, 0, p);
        os.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	n, _ := strconv.Atoi(next())
	x, y, z := next(), next(), next()
	// Rightmost position whose z letter differs from both x and y: drop it from that class only.
	star := -1
	for i := n - 1; i >= 0; i-- {
		if z[i] != x[i] && z[i] != y[i] {
			star = i
			break
		}
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	if star < 0 {
		w.WriteString("-1\n")
		return
	}
	const alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
	full := "[" + alpha + "]"
	reduced := "[" + strings.Replace(alpha, string(z[star]), "", 1) + "]"
	for i := 0; i < n; i++ {
		if i == star {
			w.WriteString(reduced)
		} else {
			w.WriteString(full)
		}
	}
	w.WriteByte('\n')
}
